import ctypes
import os

# Load the libraries
ctypes.CDLL('/usr/local/gsl/lib/libgslcblas.so', mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL('/usr/local/gsl/lib/libgsl.so')

# Define the function prototype
# gsl_odeiv_control_standard_new(double eps_abs, double eps_rel, double a_y, double a_dydt)
gsl.gsl_odeiv_control_standard_new.restype = ctypes.POINTER(ctypes.c_void_p)
gsl.gsl_odeiv_control_standard_new.argtypes = [ctypes.c_double, ctypes.c_double, ctypes.c_double, ctypes.c_double]

# Function to create a new control object
def create_control(eps_abs, eps_rel, a_y, a_dydt):
    if eps_abs < 0 or eps_rel < 0 or a_y < 0 or a_dydt < 0:
        raise ValueError('All input parameters must be non-negative')
    control_ptr = gsl.gsl_odeiv_control_standard_new(eps_abs, eps_rel, a_y, a_dydt)
    if not control_ptr:
        raise RuntimeError('Failed to create control object')
    return control_ptr

# Assertion tests
def assert_test():
    # Test with valid parameters
    control = create_control(1e-6, 1e-6, 1.0, 0.0)
    assert control is not None, 'Control object should not be None'

    # Test with invalid parameters (negative values)
    try:
        create_control(-1e-6, 1e-6, 1.0, 0.0)
    except ValueError as e:
        assert str(e) == 'All input parameters must be non-negative', 'Expected ValueError for negative eps_abs'

    try:
        create_control(1e-6, -1e-6, 1.0, 0.0)
    except ValueError as e:
        assert str(e) == 'All input parameters must be non-negative', 'Expected ValueError for negative eps_rel'

    try:
        create_control(1e-6, 1e-6, -1.0, 0.0)
    except ValueError as e:
        assert str(e) == 'All input parameters must be non-negative', 'Expected ValueError for negative a_y'

    try:
        create_control(1e-6, 1e-6, 1.0, -0.1)
    except ValueError as e:
        assert str(e) == 'All input parameters must be non-negative', 'Expected ValueError for negative a_dydt'

if __name__ == '__main__':
    assert_test()
